import {
  applyNativeDelta,
  inspectNativeTotalSpec,
  nativeLegacySectionHash,
  nativeRequirementSectionHash,
  nativeTotalSpecHash,
  parseNativeDelta,
  renderNativeDelta,
} from '../../../domains/comet-native/native-delta-spec.js';
