function preparedSupervisor(run: WorkflowRun) {
  expect(run.actions.filter(({ stepId }) => stepId === 'supervisor.prepare')).toMatchObject([
    { status: 'succeeded' },
  ]);
  expect(run.actions.filter(({ stepId }) => stepId === 'supervisor.child.prepare')).toMatchObject([
    { status: 'succeeded' },
    { status: 'succeeded' },
  ]);
